mapper.select:
select t2.accntNum,coa1.accntName,coa1.acctlevel as accntLevel,coa1.ACCNTCATEGORY as accntCategory, coa1.acctisleaf as accntIsLeaf,po1.PORTFOLIO as portnum,po1.shortCode as portCode, po1.PORT_NAME as portName,t2.drFunc,t2.crFunc,t2.drLocal,t2.crLocal,t2.localCur from (select coa.accntNum,round(sum(t1.drFunc),2) as drFunc,round(sum(t1.crFunc),2) as crFunc, round(sum(t1.drLocal),2) as drLocal,round(sum(t1.crLocal),2) as crLocal,max(t1.localCur) as localCur from (select vd.accountnum as accntNum,round(sum(vd.dr_func),2) as drFunc,round(sum(vd.cr_func),2) as crFunc, round(sum(vd.DR_LOCAL),2) as drLocal,round(sum(vd.CR_LOCAL),2) as crLocal,max(vd.localcurrency) as localCur from voucher v, voucherdetails vd where v.vouchernum=vd.vouchernum and v.portfolionum in
#{item}
and v.ledgerdate<=#{closeDate} group by vd.accountnum) t1,portfolio_hdr po, Coaa coa where po.chartnumber=coa.chartnumber and po.portfolio=#{portnum} and instr(t1.accntNum, coa.accntnum)=1 group by coa.accntnum) t2, portfolio_hdr po1, Coaa coa1 where po1.portfolio=#{portnum} and po1.chartnumber=coa1.chartnumber and t2.accntNum=coa1.accntnum order by t2.accntNum asc

mapper.delete:

begin
delete from voucherDetails where vouchernum in (select vouchernum from voucher 
	where ledgerDate>=#{ledgerDate} and portfolionum=#{portnum} and journalSourceCode=#{journalType});
delete from Voucher where ledgerDate>=#{ledgerDate} and portfolionum=#{portnum} and journalSourceCode=#{journalType};
end;

mapper.select:
select distinct v.* from Voucher v, VoucherDetails vd where v.vouchernum=vd.vouchernum and v.portfolionum in

			#{item}


	and v.ledgerDate>=#{startDate} and v.ledgerDate<#{endDate}


	and v.journalSourceCode=#{journalType}


	and vd.securityID=#{secID}


	and vd.accountNum=#{acctnum}

order by v.vouchernum asc
